// Construct daily index URL and prepare user list
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');
const dateStr = `${year}${month}${day}`;

const fihristUrl = `https://www.resmigazete.gov.tr/fihrist?tarih=${year}-${month}-${day}`;
const fallbackUrl = 'https://www.resmigazete.gov.tr/';

const users = $input.all().map(item => item.json);

return [{
  json: {
    dateStr,
    targetUrl: fallbackUrl,
    fihristUrl,
    users
  }
}];

// Extract legislation links from Firecrawl response
const response = $input.first().json;
const prepData = $('3. Prepare Index Parameters').first().json;

let rawLinks = [];
if (response.data && Array.isArray(response.data.links)) {
  rawLinks = response.data.links;
}

// Parse links with titles from Markdown body
const linksWithTitles = [];
if (response.data && response.data.markdown) {
  const md = response.data.markdown;
  const linkRegex = /\[([^\]]+)\]\((https?:\/\/[^\)]+|\/[^\)]+)\)/g;
  let match;
  while ((match = linkRegex.exec(md)) !== null) {
    let href = match[2];
    if (href.startsWith('/')) {
      href = 'https://www.resmigazete.gov.tr' + href;
    }
    const title = match[1].trim();
    if (href.includes('resmigazete.gov.tr') && (href.includes('/eskiler/') || href.includes('/ilanlar/'))) {
      linksWithTitles.push({ title, url: href });
    }
  }
}

// Include raw link list
for (const u of rawLinks) {
  const url = typeof u === 'string' ? u : u.url;
  if (url && (url.includes('/eskiler/') || url.includes('/ilanlar/') || url.includes('/mevzuat/')) && !linksWithTitles.some(l => l.url === url)) {
    linksWithTitles.push({ title: 'Resmi Gazete Mevzuati', url });
  }
}

// Filter individual acts and exclude monolithic gazette PDF when discrete articles exist
const hasSpecificActs = linksWithTitles.some(l => /\d{8}-\d+\.(htm|html|pdf)/i.test(l.url));
let finalLinks = linksWithTitles.filter(l => {
  if (hasSpecificActs && /\/\d{8}\.pdf$/i.test(l.url)) {
    return false; // Skip monolithic daily full-issue PDF, scan discrete acts
  }
  return !l.url.endsWith('/eskiler/') && !l.url.endsWith('eskiler.htm');
});

// Natural sorting
finalLinks.sort((a, b) => a.url.localeCompare(b.url, undefined, { numeric: true, sensitivity: 'base' }));

// Deduplicate links
const seen = new Set();
const uniqueLinks = [];
for (const item of finalLinks) {
  if (!seen.has(item.url)) {
    seen.add(item.url);
    uniqueLinks.push(item);
  }
}

return [{
  json: {
    targetUrl: prepData.targetUrl,
    totalItems: uniqueLinks.length,
    items: uniqueLinks,
    users: prepData.users
  }
}];

// Expand legislation items for sequential loop processing
const parsed = $('5. Parse Legislation Links').first().json;
const crawlLogId = $input.first().json.id;

return parsed.items.map(item => ({
  json: {
    crawlLogId,
    title: item.title,
    url: item.url,
    users: parsed.users
  }
}));

// Full-text search and match classification (TITLE vs BODY_TEXT vs PDF_CONTENT)
function trNormalize(str) {
  return (str || '')
    .replace(/İ/g, 'i')
    .replace(/I/g, 'ı')
    .toLocaleLowerCase('tr-TR');
}

const allInputs = $input.all();
const upstreamItems = $('7. Sequence Items (Pre-Loop)').all();
const matches = [];

for (let i = 0; i < allInputs.length; i++) {
  const firecrawlRes = allInputs[i].json;
  const itemData = upstreamItems[i] ? upstreamItems[i].json : {};

  const url = itemData.url || firecrawlRes.data?.metadata?.sourceURL || firecrawlRes.data?.metadata?.url || '';
  const legislationTitle = (firecrawlRes.data?.metadata?.title || itemData.title || url).trim();
  const bodyMarkdown = (firecrawlRes.data?.markdown || '').trim();
  const isPdf = url.toLowerCase().endsWith('.pdf');
  const crawlLogId = itemData.crawlLogId || 1;
  const users = itemData.users || [];

  if (!bodyMarkdown && !legislationTitle) continue;

  const normTitle = trNormalize(legislationTitle);
  const normBody = trNormalize(bodyMarkdown);

  for (const user of users) {
    const keywords = Array.isArray(user.keywords) ? user.keywords : [user.keywords];
    for (const kw of keywords) {
      if (!kw) continue;
      const normKw = trNormalize(kw);
      const regex = new RegExp(normKw.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&'), 'i');

      let matchLocation = null;
      if (regex.test(normTitle)) {
        matchLocation = 'TITLE';
      } else if (regex.test(normBody)) {
        matchLocation = isPdf ? 'PDF_CONTENT' : 'BODY_TEXT';
      }

      if (matchLocation) {
        matches.push({
          crawlLogId,
          recipientEmail: user.email,
          matchedKeyword: kw,
          legislationTitle,
          legislationUrl: url,
          matchLocation,
          bodySnippet: bodyMarkdown.substring(0, 4500),
          sessionId: `${crawlLogId}_${user.email}`,
          agentPrompt: `Mevzuat Başlığı: ${legislationTitle}\nKaynak Bağlantı: ${url}\nEşleşme Yeri: ${matchLocation}\nTakip Edilen Kelime: ${kw}\n\nİncelenecek Mevzuat Metni:\n${bodyMarkdown.substring(0, 4500)}\n\nLÜTFEN DİKKAT: Raporunu KESİNLİKLE %100 duru Türkçe ile hazırla. Asla Çince veya yabancı bir kelime ya da karakter (örneğin '以下' gibi) kullanma.`
        });
      }
    }
  }
}

return matches.map(m => ({ json: m }));

const text = query || '';
const hasTax = /vergi|harç|ücret|ödeme|ceza|müeyyide/i.test(text);
const hasDuty = /zorunlu|yükümlü|mecbur|etmekle mükellef/i.test(text);
const hasDeadline = /gün|ay|tarihine kadar|süre/i.test(text);
return JSON.stringify({
  mali_yuk_durumu: hasTax ? 'Mali yük, vergi, harç veya yaptırım içeren ifadeler bulunmaktadır.' : 'Mali bir yükümlülük veya ceza tespit edilmemiştir.',
  vatandas_sorumlulugu: hasDuty ? 'Vatandaş veya işletmeler için zorunlu mükellefiyet ifadeleri mevcuttur.' : 'Doğrudan zorunlu yeni bir mükellefiyet getirilmemiştir.',
  sure_bilgisi: hasDeadline ? 'Mevzuat içerisinde işlem veya yürürlük için süre/tarih kısıtları yer almaktadır.' : 'Belirlenmiş bir son tarih veya süre kısıtı belirtilmemiştir.',
  ozet_degerlendirme: (hasTax || hasDuty) ? 'YUKUMLULUK_BULUNMAKTADIR' : 'GENEL_BILGILENDIRME_VE_YUKUMLULUK_YOKTUR'
});

// Parse AI Agent output, strip markdown markers and convert to clean plain text
const allMatches = $('9. Full-Text Search & Match (Code Node)').all();
const allAgentOutputs = $input.all();

function formatToPlainText(text) {
  if (!text) return '';
  let s = text.trim().replace(/\r\n/g, '\n');

  // Remove markdown headers (###) and insert clean divider lines
  s = s.replace(/^#{1,6}\s*(.+)$/gm, (match, title) => {
    return `\n----------------------------------------------------------------------\n${title.trim()}\n----------------------------------------------------------------------`;
  });

  // Convert list markers (* or -) into bullet points (• )
  s = s.replace(/^[\*\-]\s+/gm, '• ');

  // Strip bold and italic markdown tags (** and *)
  s = s.replace(/\*\*(.*?)\*\*/g, '$1');
  s = s.replace(/\*(.*?)\*/g, '$1');
  s = s.replace(/__(.*?)__/g, '$1');
  s = s.replace(/_(.*?)_/g, '$1');

  // Strip inline code or backticks
  s = s.replace(/`([^`]+)`/g, '$1');

  // Normalize excessive newlines
  s = s.replace(/\n{3,}/g, '\n\n');

  return s.trim();
}

return allMatches.map((item, index) => {
  const matchItem = item.json;
  const agentRes = allAgentOutputs[index] ? allAgentOutputs[index].json : {};

  let rawSummary = '';
  if (agentRes && agentRes.output) {
    rawSummary = agentRes.output;
  } else if (agentRes && agentRes.text) {
    rawSummary = agentRes.text;
  } else if (agentRes && agentRes.response) {
    rawSummary = agentRes.response;
  } else {
    rawSummary = `Mevzuatta '${matchItem.matchedKeyword}' kelimesi ${matchItem.matchLocation} konumunda yakalanmıştır. Lütfen mevzuat metnini inceleyiniz.`;
  }

  const aiSummary = formatToPlainText(rawSummary);

  return {
    json: {
      ...matchItem,
      aiSummary
    }
  };
});
